contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(value <= address(c).balance);
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;
        c.sendMoney(address(this), value); if (__ESBMC_reverted()) return;
        assert(address(this).balance == myBalBefore + value && address(c).balance == cBalBefore - value && c.depositsCount() == countBefore);
    }
    receive() external payable {}
}

